548	func (r *renderer) renderTextMatch(cond *TextMatchCondition) (renderResult, error) {
549		field, ok := r.schema.Field(cond.Field)
550		if !ok {
551			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
552		}
553		column := field.columnExpr(r.dialect)
554		pattern := likePattern(cond.Mode, cond.Value)
555		return renderResult{sql: r.foldedLike(column, pattern)}, nil
556	}
